/* DUT backgrounds for this STT deck only. Generated by build_obsidian_theme.py.
   Images are embedded to avoid Obsidian/app:// relative-URL resolution issues. */
.slides-container:has(.dut-stt-marker) {
  background-color: #fff;
  background-image: url("data:image/png;base64,");
  background-size: cover;
  background-position: center;
}
.slides-container:has(.dut-stt-marker):has(.slides > section:first-child.present) { background-image: url("data:image/png;base64,"); }
.slides-container:has(.dut-stt-marker) .dut-stt-marker { display: none; }
.slides-container:has(.dut-stt-marker) .reveal {
  background: transparent;
  font-family: Arial, sans-serif;
  font-size: 30px;
  color: #14364e;
}
.slides-container:has(.dut-stt-marker) .reveal .slides > section {
  background: transparent;
  text-align: left;
  line-height: 1.4;
  padding: 20px 0 100px;
  box-sizing: border-box;
}
.slides-container:has(.dut-stt-marker) .reveal h3 {
  font-family: Arial, sans-serif;
  font-size: 1.3em;
  color: #075486;
  text-transform: none;
}
.slides-container:has(.dut-stt-marker) .reveal a { color: #075486; }
.slides-container:has(.dut-stt-marker) .reveal table { font-size: 0.9em; }
.slides-container:has(.dut-stt-marker) .reveal th { color: #075486; }
.slides-container:has(.dut-stt-marker) .reveal th, .slides-container:has(.dut-stt-marker) .reveal td { border-color: #b7c9d5; }
.slides-container:has(.dut-stt-marker) .reveal img { margin: 10px 0; }
.slides-container:has(.dut-stt-marker) .reveal .slides > section:first-child { padding-left: 180px; }
.slides-container:has(.dut-stt-marker) .reveal .slides > section:first-child h3 { color: #ffe600; font-size: 1.6em; }
.slides-container:has(.dut-stt-marker) .reveal .slides > section:first-child p { color: #fff; }
